#include "scheduler.h"

#include <assert.h>
#include <stdio.h>

static void test_bulk_promote_is_atomic_on_invalid_id(void) {
    Scheduler s;
    scheduler_init(&s);

    int p1 = scheduler_submit(&s, 1, "a");
    int fake_id = p1 + 9999;

    int ids[2] = {p1, fake_id};
    int result = scheduler_bulk_promote(&s, 2, ids);
    assert(result == 0);

    JobState state;
    assert(scheduler_find_state(&s, p1, &state) == 1);
    assert(state == JOB_PENDING);
}

static void test_bulk_promote_respects_max_concurrent(void) {
    Scheduler s;
    scheduler_init(&s);
    scheduler_set_max_concurrent(&s, 1);

    int p1 = scheduler_submit(&s, 1, "a");
    int p2 = scheduler_submit(&s, 1, "b");

    int ids[2] = {p1, p2};
    int result = scheduler_bulk_promote(&s, 2, ids);
    assert(result == 0);
    assert(s.running_count == 0);
}

int main(void) {
    test_bulk_promote_is_atomic_on_invalid_id();
    test_bulk_promote_respects_max_concurrent();
    printf("PASS\n");
    return 0;
}

