#pragma once

#include "job.h"
#include "queue.h"

#define SCHEDULER_MAX_RUNNING 256
#define SCHEDULER_MAX_HISTORY 256
#define SCHEDULER_UNLIMITED -1

typedef struct {
    JobQueue pending;
    Job running[SCHEDULER_MAX_RUNNING];
    int running_count;
    Job history[SCHEDULER_MAX_HISTORY];
    int history_count;
    int max_concurrent;
} Scheduler;

void scheduler_init(Scheduler *s);

void scheduler_set_max_concurrent(Scheduler *s, int max_concurrent);

/* Submits a new pending job; returns its id, or -1 if the queue is full. */
int scheduler_submit(Scheduler *s, int priority, const char *payload);

/* Moves the highest-priority pending job to RUNNING; writes its id to
 * *out_id. Returns 1 on success, 0 if nothing is pending or the
 * scheduler is at max_concurrent capacity. */
int scheduler_run_next(Scheduler *s, int *out_id);

/* Promotes `count` SPECIFIC pending jobs (by id, not just the next
 * highest-priority ones) to RUNNING in one call. Validates that EVERY
 * id in `ids` currently refers to a PENDING job BEFORE promoting any
 * of them - one bad id anywhere in the list must leave every job's
 * state completely unchanged. Also validates the WHOLE batch against
 * max_concurrent (running_count + count) before promoting anything.
 * Returns 1 on success, 0 (nothing promoted) otherwise. */
int scheduler_bulk_promote(Scheduler *s, int count, const int ids[]);

/* Marks a RUNNING job DONE and moves it to history.
 * Returns 1 on success, 0 if the id isn't currently running. */
int scheduler_complete(Scheduler *s, int id);

/* Marks a RUNNING job FAILED and moves it to history.
 * Returns 1 on success, 0 if the id isn't currently running. */
int scheduler_fail(Scheduler *s, int id);

/* Writes the job's current state to *out_state. Returns 1 if found
 * (pending, running, or in history), 0 otherwise. */
int scheduler_find_state(const Scheduler *s, int id, JobState *out_state);

