#include "scheduler.h"

void scheduler_init(Scheduler *s) {
    queue_init(&s->pending);
    s->running_count = 0;
    s->history_count = 0;
    s->max_concurrent = SCHEDULER_UNLIMITED;
}

void scheduler_set_max_concurrent(Scheduler *s, int max_concurrent) {
    s->max_concurrent = max_concurrent;
}

int scheduler_submit(Scheduler *s, int priority, const char *payload) {
    return queue_push(&s->pending, priority, payload);
}

int scheduler_run_next(Scheduler *s, int *out_id) {
    if (s->running_count >= SCHEDULER_MAX_RUNNING) {
        return 0;
    }
    if (s->max_concurrent != SCHEDULER_UNLIMITED && s->running_count >= s->max_concurrent) {
        return 0;
    }
    Job job;
    if (!queue_pop(&s->pending, &job)) {
        return 0;
    }
    job.state = JOB_RUNNING;
    s->running[s->running_count++] = job;
    *out_id = job.id;
    return 1;
}

static int find_pending_index(Scheduler *s, int id) {
    for (int i = 0; i < s->pending.count; i++) {
        if (s->pending.jobs[i].id == id && s->pending.jobs[i].state == JOB_PENDING) {
            return i;
        }
    }
    return -1;
}

static void remove_pending_at(Scheduler *s, int idx) {
    for (int i = idx; i < s->pending.count - 1; i++) {
        s->pending.jobs[i] = s->pending.jobs[i + 1];
    }
    s->pending.count--;
}

int scheduler_bulk_promote(Scheduler *s, int count, const int ids[]) {
    if (count <= 0) {
        return 0;
    }
    for (int i = 0; i < count; i++) {
        if (find_pending_index(s, ids[i]) < 0) {
            return 0;
        }
    }
    if (s->running_count + count > SCHEDULER_MAX_RUNNING) {
        return 0;
    }
    if (s->max_concurrent != SCHEDULER_UNLIMITED && s->running_count + count > s->max_concurrent) {
        return 0;
    }
    for (int i = 0; i < count; i++) {
        int idx = find_pending_index(s, ids[i]);
        Job job = s->pending.jobs[idx];
        remove_pending_at(s, idx);
        job.state = JOB_RUNNING;
        s->running[s->running_count++] = job;
    }
    return 1;
}

static int find_running_index(Scheduler *s, int id) {
    for (int i = 0; i < s->running_count; i++) {
        if (s->running[i].id == id) {
            return i;
        }
    }
    return -1;
}

static int finish_job(Scheduler *s, int id, JobState final_state) {
    int idx = find_running_index(s, id);
    if (idx < 0) {
        return 0;
    }
    Job job = s->running[idx];
    job.state = final_state;
    for (int i = idx; i < s->running_count - 1; i++) {
        s->running[i] = s->running[i + 1];
    }
    s->running_count--;
    if (s->history_count < SCHEDULER_MAX_HISTORY) {
        s->history[s->history_count++] = job;
    }
    return 1;
}

int scheduler_complete(Scheduler *s, int id) {
    return finish_job(s, id, JOB_DONE);
}

int scheduler_fail(Scheduler *s, int id) {
    return finish_job(s, id, JOB_FAILED);
}

int scheduler_find_state(const Scheduler *s, int id, JobState *out_state) {
    for (int i = 0; i < s->pending.count; i++) {
        if (s->pending.jobs[i].id == id) {
            *out_state = s->pending.jobs[i].state;
            return 1;
        }
    }
    for (int i = 0; i < s->running_count; i++) {
        if (s->running[i].id == id) {
            *out_state = s->running[i].state;
            return 1;
        }
    }
    for (int i = 0; i < s->history_count; i++) {
        if (s->history[i].id == id) {
            *out_state = s->history[i].state;
            return 1;
        }
    }
    return 0;
}

